import { array, zeros } from "numpy-ts";
export function make_even(iterable_1, iterable_2) {
    const list_1 = Array.from(iterable_1);
    const list_2 = Array.from(iterable_2);
    const len_list_1 = list_1.length;
    const len_list_2 = list_2.length;
    const length = Math.max(len_list_1, len_list_2);
    if (length === 0) {
        return [[], []];
    }
    return [
        Array.from({ length }, (_, n) => list_1[Math.floor((n * len_list_1) / length)]),
        Array.from({ length }, (_, n) => list_2[Math.floor((n * len_list_2) / length)]),
    ];
}
export function tuplify(obj) {
    if (typeof obj === "string")
        return [obj];
    if (isIterableObject(obj))
        return Array.from(obj);
    return [obj];
}
export function uniq_chain(...args) {
    function* generator() {
        const unique_items = new Set();
        for (const iterable of args) {
            for (const x of iterable) {
                if (unique_items.has(x))
                    continue;
                unique_items.add(x);
                yield x;
            }
        }
    }
    return generator();
}
function isIterableObject(value) {
    return (value !== null &&
        value !== undefined &&
        typeof value[Symbol.iterator] === "function");
}
export function listify(obj) {
    if (typeof obj === "string")
        return [obj];
    if (isIterableObject(obj))
        return Array.from(obj);
    return [obj];
}
export function batch_by_property(items, property_func) {
    const batch_prop_pairs = [];
    let curr_batch = [];
    let curr_prop = null;
    for (const item of items) {
        const prop = property_func(item);
        if (prop !== curr_prop) {
            if (curr_batch.length > 0)
                batch_prop_pairs.push([curr_batch, curr_prop]);
            curr_prop = prop;
            curr_batch = [item];
        }
        else {
            curr_batch.push(item);
        }
    }
    if (curr_batch.length > 0)
        batch_prop_pairs.push([curr_batch, curr_prop]);
    return batch_prop_pairs;
}
export function list_difference_update(l1, l2) {
    const l2set = new Set(l2);
    return [...l1].filter((e) => !l2set.has(e));
}
export function list_update(l1, l2) {
    const l2list = Array.from(l2);
    return [...list_difference_update(l1, l2list), ...l2list];
}
export function resize_array(nparray, length) {
    const { rows, flat } = elementRows(nparray);
    if (rows.length === length) {
        if (isNDArrayLike(nparray))
            return nparray;
        return array(flat ? rows.map((row) => row[0]) : rows);
    }
    // np.resize tiles the input in C-order; with the trailing shape preserved
    // this is exactly row cycling.
    if (rows.length === 0) {
        const rest = nparray.shape?.slice(1) ?? [];
        return zeros([length, ...rest]);
    }
    const out = Array.from({ length }, (_, i) => [...(rows[i % rows.length] ?? [])]);
    return array(flat ? out.map((row) => row[0]) : out);
}
export function stretch_array_to_length(nparray, length) {
    const raw = nparray.toArray();
    const rowsArray = Array.isArray(raw) ? raw : [];
    const curr_len = rowsArray.length;
    if (curr_len > length) {
        const error = new Error("Trying to stretch array to a length shorter than its own");
        error.name = "Warning";
        throw error;
    }
    const picked = Array.from({ length }, (_, i) => rowsArray[Math.trunc((i / length) * curr_len)]);
    return array(picked);
}
export function resize_preserving_order(nparray, length) {
    const raw = nparray.toArray();
    const rowsArray = Array.isArray(raw) ? raw : [];
    if (rowsArray.length === 0) {
        const rest = nparray.shape.slice(1);
        const total = rest.reduce((acc, dim) => acc * dim, length);
        return array(new Array(total).fill(0)).reshape(length, ...rest);
    }
    if (rowsArray.length === length)
        return nparray;
    const indices = Array.from({ length }, (_, i) => Math.floor((i * rowsArray.length) / length));
    const picked = indices.map((index) => rowsArray[index]);
    return array(picked);
}
export function hash_obj(obj) {
    if (obj !== null && typeof obj === "object") {
        if (obj instanceof Map) {
            const pairs = [...obj.entries()].map(([k, v]) => [hash_obj(k), hash_obj(v)]);
            pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
            return hashTuple(pairs.map(([k, v]) => k * 31 + v));
        }
        if (obj instanceof Set) {
            const hashes = [...obj].map(hash_obj).sort((a, b) => a - b);
            return hashTuple(hashes);
        }
        if (Array.isArray(obj))
            return hashTuple(obj.map(hash_obj));
        if (isNDArrayLike(obj)) {
            return hashTuple(JSON.stringify(obj.toArray())
                .split("")
                .map((ch) => ch.charCodeAt(0)));
        }
        if (obj.constructor?.name === "Object") {
            const entries = Object.entries(obj).map(([k, v]) => [hash_obj(k), hash_obj(v)]);
            entries.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
            return hashTuple(entries.map(([k, v]) => k * 31 + v));
        }
    }
    return hashPrimitive(obj);
}
function hashTuple(items) {
    let hash = 0x345678;
    for (const item of items) {
        hash = Math.imul(hash ^ (item | 0), 1000003);
        hash ^= hash >>> 16;
    }
    hash = Math.imul(hash ^ items.length, 0x45d9f3b);
    hash ^= hash >>> 16;
    return hash | 0;
}
function hashPrimitive(value) {
    if (value === null || value === undefined) {
        const key = value === null ? "None" : "NoneType";
        return stringHash(key);
    }
    switch (typeof value) {
        case "number":
            if (Number.isNaN(value))
                return 0;
            if (Object.is(value, -0))
                return stringHash("-0.0");
            return stringHash(`float:${value}`);
        case "bigint":
            return stringHash(`int:${value}`);
        case "boolean":
            return value ? 1 : 0;
        case "string":
            return stringHash(value);
        case "function":
            return stringHash(value.toString());
        default:
            return stringHash(String(value));
    }
}
function stringHash(value) {
    let hash = 0;
    for (let i = 0; i < value.length; i += 1) {
        hash = Math.imul(31, hash) + value.charCodeAt(i);
        hash |= 0;
    }
    return hash;
}
function ensureHashable(value) {
    if (Array.isArray(value) || value instanceof Map || value instanceof Set || (value !== null && typeof value === "object" && value.constructor?.name === "Object")) {
        throw new TypeError(`unhashable type: '${Array.isArray(value) ? "list" : value instanceof Map ? "dict" : value instanceof Set ? "set" : "dict"}'`);
    }
}
export function remove_list_redundancies(lst) {
    if (lst instanceof Set)
        throw new TypeError("'set' object is not reversible");
    const values = typeof lst === "string" ? [...lst] : Array.isArray(lst) ? [...lst] : Array.from(lst);
    const reversedResult = [];
    // Python uses a hash set here; the previous `used.some(sameValue)` scan was
    // O(n^2) and dominated `get_mobjects_to_display` on big 3D families (a
    // 1000-face sphere spent ~14 ms per frame deduplicating).  Object identity
    // (the common case: Mobjects) and string equality map directly onto a Set;
    // numbers need Python's `==` semantics where NaN never equals itself.
    const objectSeen = new Set();
    const numberSeen = new Set();
    for (let index = values.length - 1; index >= 0; index -= 1) {
        const value = values[index];
        ensureHashable(value);
        let duplicate;
        if (typeof value === "number" || typeof value === "boolean") {
            const numeric = Number(value);
            // NaN is never a duplicate (Python's `nan in {nan}` is False).
            duplicate = !Number.isNaN(numeric) && numberSeen.has(numeric);
            if (!duplicate && !Number.isNaN(numeric))
                numberSeen.add(numeric);
        }
        else {
            duplicate = objectSeen.has(value);
            if (!duplicate)
                objectSeen.add(value);
        }
        if (!duplicate) {
            reversedResult.push(value);
        }
    }
    reversedResult.reverse();
    return reversedResult;
}
export function adjacent_n_tuples(objects, n) {
    // Python builds `zip(*(... for k in range(n)))` with no iterables when
    // n <= 0, so plain `zip()` yields nothing (verified against manim 0.21.0:
    // negative n returns []).
    if (n <= 0)
        return [];
    if (!Array.isArray(objects) && !isIterableObject(objects)) {
        throw new TypeError(`'${typeName(objects)}' object is not subscriptable`);
    }
    const items = Array.isArray(objects) ? [...objects] : Array.from(objects);
    const result = [];
    for (let index = 0; index < items.length; index += 1) {
        const group = [];
        for (let k = 0; k < n; k += 1)
            group.push(items[(index + k) % items.length]);
        result.push(group);
    }
    return result;
}
export function adjacent_pairs(objects) {
    return adjacent_n_tuples(objects, 2);
}
export function resize_with_interpolation(nparray, length) {
    const { rows, flat } = elementRows(nparray);
    if (rows.length === length) {
        if (isNDArrayLike(nparray))
            return nparray;
        return array(flat ? rows.map((row) => row[0]) : rows);
    }
    const count = rows.length;
    const cont_indices = Array.from({ length }, (_, i) => (length === 1 ? 0 : (i * (count - 1)) / (length - 1)));
    const out = cont_indices.map((ci) => {
        const lh = Math.trunc(ci);
        const rh = Math.ceil(ci);
        const a = ci % 1;
        const width = Math.max(rows[lh]?.length ?? 0, rows[rh]?.length ?? 0);
        return Array.from({ length: width }, (_, c) => (1 - a) * (rows[lh]?.[c] ?? 0) + a * (rows[rh]?.[c] ?? 0));
    });
    return array(flat ? out.map((row) => row[0]) : out);
}
function typeName(value) {
    if (value === null || value === undefined)
        return "NoneType";
    if (typeof value === "number")
        return Number.isInteger(value) ? "int" : "float";
    if (typeof value === "string")
        return "str";
    if (typeof value === "boolean")
        return "bool";
    return typeof value;
}
function isNDArrayLike(value) {
    return (typeof value === "object" &&
        value !== null &&
        "shape" in value &&
        "copy" in value);
}
function elementRows(value) {
    if (isNDArrayLike(value)) {
        const arr = value;
        const raw = arr.toArray();
        if (arr.shape.length <= 1) {
            const items = (Array.isArray(raw) ? raw : [raw]);
            return { rows: items.map((item) => [Number(item)]), flat: true };
        }
        return { rows: raw.map((row) => (Array.isArray(row) ? row : [row]).map(Number)), flat: false };
    }
    if (Array.isArray(value)) {
        if (value.length === 0)
            return { rows: [], flat: false };
        if (typeof value[0] === "number" || typeof value[0] === "bigint") {
            return { rows: value.map((item) => [Number(item)]), flat: true };
        }
        return { rows: value.map((row) => (Array.isArray(row) ? row : [row]).map(Number)), flat: false };
    }
    return { rows: [], flat: false };
}
